"""Shared Pydantic data schemas and Agent State representation."""

from typing import List, Dict, Any, Optional, Literal
from pydantic import BaseModel, Field


class PlanStep(BaseModel):
    """An individual step in the implementation plan."""

    step_number: int
    description: str
    target_file: Optional[str] = None
    completed: bool = False


class TaskPlan(BaseModel):
    """Structured plan generated by the Supervisor Agent."""

    goal: str
    architecture_notes: str
    steps: List[PlanStep] = Field(default_factory=list)


class TestResult(BaseModel):
    """Structured outcome of running pytest in sandbox."""

    __test__ = False
    passed: bool
    summary: str
    stdout: str = ""
    stderr: str = ""
    error_trace: Optional[str] = None


class AgentState(BaseModel):
    """Central state passed across nodes in the multi-agent graph."""

    user_prompt: str
    plan: Optional[TaskPlan] = None
    generated_files: List[str] = Field(default_factory=list)
    latest_test_result: Optional[TestResult] = None
    healing_cycle: int = 0
    status: Literal["planning", "coding", "testing", "healing", "completed", "failed"] = "planning"
    history: List[Dict[str, Any]] = Field(default_factory=list)
